const PREVIEW_EP_LABELS = {
  ko: { section: 'EPISODES', count: '3편의 단편 연작', director: '감독', writer: '각본', cast: '출연', genre: '장르', runtime: '러닝타임', synopsis: '시놉시스' },
  en: { section: 'EPISODES', count: '3 short films', director: 'Director', writer: 'Screenplay', cast: 'Cast', genre: 'Genre', runtime: 'Runtime', synopsis: 'Synopsis' }
};

function previewEpLabel(key) {
  return (PREVIEW_EP_LABELS[currentLanguage] || PREVIEW_EP_LABELS.ko)[key];
}

function renderPreviewEpisodeCard(episode) {
  const keywords = (episode.keywords[currentLanguage] || episode.keywords.ko || [])
    .map(word => `<span class="ep-keyword">#${escapeHtml(word)}</span>`).join('');

  return `
    <article class="ep-card">
      <div class="ep-card-head">
        <span class="ep-badge">EP.${episode.ep}</span>
        <h4 class="ep-title">${escapeHtml(localized(episode.title))}</h4>
        <span class="ep-meta">${episode.year} · ${escapeHtml(localized(episode.genre))} · ${escapeHtml(episode.running_time)}</span>
      </div>

      ${localized(episode.logline) ? `<p class="ep-logline">"${escapeHtml(localized(episode.logline))}"</p>` : ''}

      <p class="synopsis-text ep-synopsis">${escapeHtml(localized(episode.synopsis))}</p>

      <table class="credits-table ep-credits">
        ${renderCreditRow(previewEpLabel('director'), localized(episode.director))}
        ${renderCreditRow(previewEpLabel('writer'), localized(episode.writer))}
        ${renderCreditRow(previewEpLabel('cast'), localized(episode.cast))}
      </table>

      ${keywords ? `<div class="ep-keywords">${keywords}</div>` : ''}
    </article>
  `;
}

function renderPreviewEpisodeSection(episodes) {
  return `
    <div class="detail-section ep-section">
      <h3>${previewEpLabel('section')} <span class="ep-count">${previewEpLabel('count')}</span></h3>
      <div class="ep-list">
        ${episodes.map(renderPreviewEpisodeCard).join('')}
      </div>
    </div>
  `;
}

/* main.js 의 renderDetailView 를 감싸서, 공포 영화 시리즈일 때만
   기존 SYNOPSIS / CAST & CREW 섹션을 에피소드 섹션으로 교체 */
const originalRenderDetailView = renderDetailView;

renderDetailView = function (film) {
  const html = originalRenderDetailView(film);
  if (!film || film.id !== PREVIEW_HORROR_FILM_ID) return html;

  const container = document.createElement('div');
  container.innerHTML = html;

  const sections = [...container.querySelectorAll('.detail-view > .detail-section')];
  const synopsisSection = sections.find(section => section.querySelector('h3')?.textContent.trim() === 'SYNOPSIS');
  const creditsSection = sections.find(section => section.querySelector('h3')?.textContent.trim().startsWith('CAST'));

  const episodeWrap = document.createElement('div');
  episodeWrap.innerHTML = renderPreviewEpisodeSection(PREVIEW_HORROR_EPISODES);
  const episodeSection = episodeWrap.firstElementChild;

  const anchor = synopsisSection || creditsSection;
  if (anchor) {
    anchor.replaceWith(episodeSection);
  } else {
    container.querySelector('.detail-view')?.appendChild(episodeSection);
  }
  if (creditsSection && creditsSection !== anchor) creditsSection.remove();

  return container.innerHTML;
};

